import { apiClient } from './client'
import type {
  AuthTokens,
  ChangePasswordRequest,
  LoginRequest,
  RegisterRequest,
  UpdateMeRequest,
  User,
} from '@/types'

export const authApi = {
  async login(body: LoginRequest): Promise<AuthTokens> {
    const { data } = await apiClient.post<AuthTokens>('/auth/login', body)
    return data
  },

  async register(body: RegisterRequest): Promise<AuthTokens> {
    const { data } = await apiClient.post<AuthTokens>('/auth/register', body)
    return data
  },

  async refresh(refreshToken: string): Promise<AuthTokens> {
    const { data } = await apiClient.post<AuthTokens>('/auth/refresh', {
      refresh_token: refreshToken,
    })
    return data
  },

  async logout(): Promise<void> {
    await apiClient.post('/auth/logout')
  },

  async me(): Promise<User> {
    const { data } = await apiClient.get<User>('/auth/me')
    return data
  },

  async updateMe(body: UpdateMeRequest): Promise<User> {
    const { data } = await apiClient.patch<User>('/auth/me', body)
    return data
  },

  async changePassword(body: ChangePasswordRequest): Promise<void> {
    await apiClient.post('/auth/change-password', body)
  },
}

Now let's write the code.

MarkdownView.vue:

```vue
<script setup lang="ts">
import { computed } from 'vue'
import { ElMessageBox } from 'element-plus'

import { renderMarkdown } from '@/utils/markdown'

const props = defineProps<{
  content: string
}>()

const html = computed(() => renderMarkdown(props.content))

/** 直接放行的协议：邮件与电话由系统处理，不需要离开确认。 */
const PASS_THROUGH_PROTOCOLS = new Set(['mailto:', 'tel:'])

function parseHref(href: string): URL | null {
  try {
    return new URL(href, window.location.href)
  } catch {
    return null
  }
}

async function confirmExternal(url: URL): Promise<void> {
  try {
    await ElMessageBox.confirm(
      `将离开 Agent Hub，在新标签页打开外部链接：${url.host}`,
      '打开外部链接',
      {
        confirmButtonText: '继续访问',
        cancelButtonText: '取消',
        type: 'warning',
      },
    )
  } catch {
    // 用户取消或关闭弹窗：不打开。
    return
  }
  window.open(url.href, '_blank', 'noopener,noreferrer')
}

/** 事件委托：外链二次确认，同源、锚点、邮件与电话保持默认行为。 */
async function onRootClick(event: MouseEvent): Promise<void> {
  // 修饰键点击（新标签页/新窗口/下载）与鼠标中键保留浏览器默认行为。
  if (event.defaultPrevented) return
  if (event.button !== 0 || event.ctrlKey || event.metaKey || event.shiftKey || event.altKey) return

  const target = event.target
  if (!(target instanceof Element)) return
  const anchor = target.closest('a[href]')
  if (!anchor) return

  const href = anchor.getAttribute('href')?.trim() ?? ''
  if (!href || href.startsWith('#')) return
  if (PASS_THROUGH_PROTOCOLS.has(parseHref(href)?.protocol ?? '')) return

  const url = parseHref(href)
  if (!url) {
    event.preventDefault()
    return
  }
  // 非 HTTP(S) 协议（如 javascript:、data:）不弹确认也不打开。
  if (url.protocol !== 'http:' && url.protocol !== 'https:') {
    event.preventDefault()
    return
  }
  // 同源链接留在应用内，保持默认导航。
  if (url.origin === window.location.origin) return

  event.preventDefault()
  await confirmExternal(url)
}
```

Wait, `PASS_THROUGH_PROTOCOLS` check: parseHref('mailto:a@b.com') with base http://localhost gives URL with protocol mailto:, host ''. `new URL('mailto:...', base)` works. For tel: too. Note: href.startsWith('mailto:') case-insensitive? `MAILTO:` is valid scheme case-insensitively. Use url.protocol which is lowercased. Since we compute url twice, restructure:

```ts
if (!href || href.startsWith('#')) return
const url = parseHref(href)
if (!url) { event.preventDefault(); return }
if (PASS_THROUGH_PROTOCOLS.has(url.protocol)) return
if (url.protocol !== 'http:' && url.protocol !== 'https:') { event.preventDefault(); return }
if (url.origin === window.location.origin) return
event.preventDefault()
await confirmExternal(url)
```

Cleaner.

Potential issue: `window.open(url.href, ...)` — for links with target and hash, url.href is normalized absolute; requirement says window.open(href,...). Better use raw href? "确认后 window.open(href,'_blank','noopener,noreferrer')". Use original raw href to preserve exact target. But normalized is equivalent for http(s). I'll pass `anchorHref` raw. Hmm, confirmExternal takes URL; can take both. Simpler: pass url for host, and href for open:

```ts
async function confirmExternal(href: string, host: string)
```

Then `await confirmExternal(href, url.host)` and window.open(href,...). Let's do that to match requirement literally.

Actually, using `url.href` vs `href`: requirement says window.open(href). Use raw href to be exact. Fine.

